class CloudCredentialRotateAPIView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def put(self, request, cred_id):
        cred = get_object_or_404(CloudCredential, id=cred_id, tenant=request.user.tenant)
        cred.access_key = request.data['access_key']
        cred.secret_key = request.data['secret_key']
        cred.save(update_fields=['access_key', 'secret_key'])
        return Response({'status': 'rotated', 'key_id': cred.id})
